expr:
return {
      kind: 'loop',
      loopKind: 'while',
      startLine,
      endLine: this.prevLine(),
      predicate,
      body,
    };

return {
      kind,
      startLine,
      endLine: lastLine,
      expr,
      head: kind,
      ...(callSite ? { callSite } : {}),
      ...(switchArms ? { switchArms } : {}),
    };

return {
        kind: 'assign',
        startLine,
        endLine: lastLine,
        expr,
        head: 'assign',
        assignTarget: lastIdentifier(lhs),
        ...(callSite ? { callSite } : {}),
        ...(switchArms ? { switchArms } : {}),
      };

return {
      kind: 'call',
      startLine,
      endLine: lastLine,
      expr,
      head: callSite.name,
      callSite,
      ...(switchArms ? { switchArms } : {}),
    };

calls.push({
          head: chain[0]!,
          tail: chain.slice(1),
          name: chain[chain.length - 1]!,
          line,
        });

const consumeDotted = (k: number): { parts: string[]; j: number } => {
    const parts: string[] = [];
    let j = k;
    while (j < tokens.length && tokens[j]!.type === 'NAME') {
      parts.push(tokens[j]!.value);
      j++;
      if (isOp(j, '.')) {
        j++;
        continue;
      }
      break;
    }
    return { parts, j };
  };

imports.push({
          module: '',
          name: alias,
          static: isStatic,
          alias: true,
          target,
          global,
          line,
        });

imports.push({
        module,
        name: last,
        static: isStatic,
        alias: false,
        target: '',
        global,
        line,
      });
